    nfits <- sflist2stanfit(nfits)
    nfits@.MISC <- sfmiscenv
    throw_sampler_warnings(nfits)
    return(nfits)
  }
  else {
    warning("some chains had errors; consider specifying chains = 1 to debug")
    message("here are whatever error messages were returned")

